public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
	int octet;
	int codepoint;
	int cont;
	int remaining;

	while (bb.limit - i >= remaining && (octet = bb.get(i++)) != 0) {
		if ((octet & 0x80) == 0) {
			codepoint = octet & 0x7F;
			remaining = 0;
		} else if ((octet & 0xE0) >= 0xC0) {
			codepoint = octet & 0x1F;
			remaining = 1;
		} else if ((octet & 0xF0) >= 0xE0) {
			codepoint = octet & 0x0F;
			remaining = 2;
		} else if ((octet & 0xF8) >= 0xF0) {
			codepoint = octet & 0x07;
			remaining = 3;
		} else {
			throw new RuntimeException("Invalid UTF-8 sequence");
		}

		for (cont = 0; cont < remaining; cont++) {
			if ((octet = bb.get(i++)) < 0x80 || octet > 0xBF) {
				throw new RuntimeException("Invalid UTF-8 sequence");
			}
			codepoint = (codepoint << 6) + (octet & 0x3F);
		}

		if (codepoint > 0xFFFF) {
			sb.append((char) (0xD800 + ((codepoint - 0x10000) >> 10)));
			sb.append((char) (0xDC00 + (codepoint & 0x3FF)));
		} else {
			sb.append((char) codepoint);
		}
	}

	return i - 1;
}

