@Override
public int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }

    // Check if the filename is in Unix format
    int unixSepIndex = filename.lastIndexOf('/');
    if (unixSepIndex >= 0) {
        return unixSepIndex;
    }

    // Check if the filename is in Windows format
    int windowsSepIndex = filename.lastIndexOf('\\');
    if (windowsSepIndex >= 0) {
        return windowsSepIndex;
    }

    return -1;
}

