public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Generate the first set of vertices
    Set<V> vertices = new LinkedHashSet<>();
    for (int i = 0; i < target.getNumVertices(); i++) {
        V vertex = target.getVertex(i);
        if (vertex.getClass().getName().equals("BipartiteVertex")) {
            vertices.add(vertex);
        }
    }

    // Generate the second set of vertices
    Set<V> nonBipartiteVertices = new LinkedHashSet<>();
    for (V vertex : target.getVertices()) {
        if (!vertices.contains(vertex)) {
            nonBipartiteVertices.add(vertex);
        }
    }

    // Generate the edges
    Set<E> edges = new LinkedHashSet<>();
    for (V vertex : vertices) {
        for (V otherVertex : nonBipartiteVertices) {
            if (target.getEdge(vertex, otherVertex) == null) {
                edges.add(target.addEdge(vertex, otherVertex));
            }
        }
    }

    resultMap.put("edges", edges);
}

