}

boolean generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    int n = resultMap.size();
    int m = n * (n - 1) / 2;
    Map<V, Set<V>> adjList = new HashMap<>();
    for (int i = 0; i < n; i++) {
        adjList.put(resultMap.get(i), new HashSet<>());
        for (int j = 0; j < m; j++) {
            V u = resultMap.get(i);
            V v = resultMap.get((j + i) % n);
            if (!u.equals(v) && !adjList.get(u).contains(v)) {
                adjList.get(u).add(v);
                target.addEdge(u, v);
            }
        }
    }
}

