}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
	int messageSize = schema.getSerializedSize(message);
	if (messageSize > MAX_SIZE) {
	    String error = "message too large (" + messageSize + " bytes)";
	    if (messageSize > LinkedBuffer.MAX_BUFFER_SIZE) {
	        error += ", consider using a larger buffer. code: " + error;
	    }
	    throw new IllegalArgumentException(error);
	}

	buffer.ensureCapacity(messageSize);
	CodedOutputStream codedOutputStream = CodedOutputStream.newInstance(buffer);
	schema.writeTo(codedOutputStream, message);
	int bytesWritten = codedOutputStream.flush();
	out.write(buffer.toByteArray());
	return bytesWritten;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSize(message);
    return writeDelimitedTo(out, size, message, schema, buffer);
}

private static <T> int writeDelimitedTo(OutputStream out, int size, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int written = 0;
    int len = size + 4; // 4 bytes for the length prefix
    byte[] bytes = new byte[len];
    ByteBuffer byteBuf = ByteBuffer.wrap(bytes);

    byteBuf.position(0);
    byteBuf.putInt(size);
    written += 4;

    byteBuf.position(4);
    written += schema.writeTo(byteBuf, message);

    out.write(bytes, 0, len);
    return written;
}

