public void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("The given bucket cannot be null!");
    }

    Bucket thisBucket = this;

    if (thisBucket == null) {
        throw new IllegalStateException("This bucket must not be null!");
    }

    if (thisBucket.getKey().compareTo(bucket.getKey()) >= 0) {
        throw new IllegalStateException("This bucket must be placed before the given bucket!");
    }

    Bucket currentBucket = thisBucket;
    while (currentBucket != null) {
        if (currentBucket == bucket) {
            break;
        }
        currentBucket = currentBucket.getNext();
    }

    if (currentBucket == null) {
        throw new IllegalStateException("The given bucket cannot be found in this data structure!");
    }

    currentBucket.setNext(thisBucket);
    thisBucket.setNext(null);
}

