public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the current mappings for the table from the index
    Mappings currentMappings = getMappings(tableName);

    // Create a new mapping to store the diff
    Mappings diffMapping = new Mappings();

    // Iterate over the input mappings and compare with the current mappings
    for (Mapping inputMapping : mappings.getMappings()) {
        String inputField = inputMapping.getField();
        if (!currentMappings.contains(inputField)) {
            // If the field does not exist in the current mappings, add it to the diff mapping
            diffMapping.add(inputMapping);
        }
    }

    return diffMapping;
}

