public List<TimeRange> buildTimeRanges(long start, long end) {


    final long maxRangeDuration = FETCH_DATA_DURATION;
    final long totalDuration = end - start;

    int numRanges = (int)Math.ceil((double)totalDuration / maxRangeDuration);
    long rangeStep = totalDuration / numRanges;

    List<TimeRange> ranges = new ArrayList<>();
    for (long i = 0; i < numRanges; i++) {
        long rangeStart = start + i * rangeStep;
        long rangeEnd = rangeStart + rangeStep - 1;
        if (i == numRanges - 1) {
            rangeEnd = end;
        }
        ranges.add(new TimeRange(rangeStart, rangeEnd));
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<TimeRange>();
    long currentStart;
    long currentEnd;
    long diff = end - start;
    if (diff < FETCH_DATA_DURATION) {
        TimeRange timeRange = new TimeRange(TimeRange.INCLUDE_START, TimeRange.INCLUDE_END, start, end);
        timeRanges.add(timeRange);
    } else {
        currentStart = start;
        currentEnd = end;

        while (diff >= FETCH_DATA_DURATION) {
            currentEnd = currentStart + FETCH_DATA_DURATION;
            TimeRange timeRange = new TimeRange(TimeRange.INCLUDE_START, TimeRange.INCLUDE_END, currentStart, currentEnd);
            timeRanges.add(timeRange);

            currentStart = currentEnd + 1;
            diff = end - currentStart;
        }

        if (diff > 0) {
            TimeRange timeRange = new TimeRange(TimeRange.INCLUDE_START, TimeRange.INCLUDE_END, currentStart, end);
            timeRanges.add(timeRange);
        }
    }

    return timeRanges;
}

