public static LinkedBuffer writeUTF8(final char[] buf, final WriteSession session, final LinkedBuffer lb) {
	final int len = buf.length;
	final byte[] bytes = new byte[len * 3];
	int i = 0;
	int j = 0;
	while (i < len) {
		final char c = buf[i++];
		if (c < 0x80) {
			bytes[j++] = (byte) (c & 0x7F);
		} else if (c < 0x800) {
			bytes[j++] = (byte) (0xC0 | ((c >> 6) & 0x1F));
			bytes[j++] = (byte) (0x80 | (c & 0x3F));
		} else if (c < 0xD800 || c > 0xDFFF) {
			bytes[j++] = (byte) (0xE0 | ((c >> 12) & 0x0F));
			bytes[j++] = (byte) (0x80 | ((c >> 6) & 0x3F));
			bytes[j++] = (byte) (0x80 | (c & 0x3F));
		} else {
			int cp = 0;
			int end = i;
			int n = 0;
			while (i < len && (c = buf[i++]) >= 0xD800 && c <= 0xDFFF) {
				cp |= (c & 0x3FF) << (2 * n);
				end = i;
			}
			cp += (0x10000 + ((cp >> 10) & 0x3FF));
		}
		bytes[j++] = (byte) (0xED | ((cp >> 18) & 0x07));
		bytes[j++] = (byte) (0x80 | ((cp >> 12) & 0x3F));
		bytes[j++] = (byte) (0x80 | ((cp >> 6) & 0x3F));
		bytes[j++] = (byte) (0x80 | (cp & 0x3F));
		i = end;
	}
	return lb.writeBytes(bytes, 0, j);
}

