public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u.getPath() == null || u.getPath().isEmpty()) {
        return pathSegments;
    }
    boolean ignoreDelimiter = u.getPath().startsWith("/");
    StringTokenizer tokenizer = new StringTokenizer(u.getPath(), "/");
    while (tokenizer.hasMoreTokens()) {
        String token = tokenizer.nextToken();
        if (decode) {
            try {
                token = URLDecoder.decode(token, DEFAULT_ENCODING);
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        pathSegments.add(new PathSegmentImpl(token, ignoreDelimiter));
    }
    return pathSegments;
}

public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    List<String> segments = new ArrayList<>();

    if (path.length() > 0) {
        if (path.charAt(0) == '/') {
            path = path.substring(1);
        }

        int index = 0;
        while (index < path.length()) {
            int nextSlashIndex = path.indexOf('/', index);
            String segment = nextSlashIndex == -1 ? path.substring(index) : path.substring(index, nextSlashIndex);

            if (decode) {
                segment = decodePathSegment(segment);
            }

            segments.add(segment);
            index = nextSlashIndex == -1 ? path.length() : nextSlashIndex + 1;
        }
    } else {
        segments.add("");
    }

    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String[] pathComponents = u.getPath().split("/", 0);
        for (String pathComponent : pathComponents) {
            if (pathComponent.isEmpty()) {
                continue;
            }
            PathSegmentImpl segment = new PathSegmentImpl();
            if (decode) {
                try {
                    segment.setPath(URLDecoder.decode(pathComponent, "UTF-8"));
                } catch (UnsupportedEncodingException e) {
                    throw new RuntimeException(e);
                }
            } else {
                segment.setPath(pathComponent);
            }
            pathSegments.add(segment);
        }
        return pathSegments;
    }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode){
    String path = u.getPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (path.isEmpty()) {
        return segments;
    }
    if (decode) {
        path = URLDecoder.decode(path, "UTF-8");
    }
    int startIndex = 0;
    int index = path.indexOf('/');
    while (index >= 0) {
        if (index > startIndex) {
            segments.add(new PathSegmentImpl(path.substring(startIndex, index)));
        }
        startIndex = index + 1;
        index = path.indexOf('/', startIndex);
    }
    if (startIndex < path.length()) {
        segments.add(new PathSegmentImpl(path.substring(startIndex)));
    }
    return segments;
}

