String unescapeJava(String str) throws Exception {
	if (str == null) {
		return null;
	}

	StringBuilder result = new StringBuilder();
	char c;
	for (int i = 0; i < str.length(); i++) {
		c = str.charAt(i);
		if (c == '\\') {
			i++;
			if (i == str.length()) {
				throw new Exception("unescapeJava: incomplete escape sequence");
			}

			c = str.charAt(i);
			switch (c) {
			case 'b':
				result.append('\b');
				break;
			case 't':
				result.append('\t');
				break;
			case 'n':
				result.append('\n');
				break;
			case 'f':
				result.append('\f');
				break;
			case 'r':
				result.append('\r');
				break;
			case '\\':
				result.append('\\');
				break;
			case '"':
				result.append('"');
				break;
			case '\'':
				result.append('\'');
				break;
			case '~':
				result.append('~');
				break;
			default:
				result.append(c);
				break;
			}
		} else {
			result.append(c);
		}
	}

	return result.toString();
}

