private int removeUnusedNodes(CategoryNode node) {
    int numRemoved = 0;
    for (CategoryNode child : node.getChildren()) {
        numRemoved += removeUnusedNodes(child);
        if (!child.isActive() && child.getNumReferences() == 0) {
            node.removeChild(child);
            ++numRemoved;
        }
    }
    return numRemoved;
}

