    // Create a new circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator();

    // Set the initial node
    circulator.setCurrent(start);

    // Loop until we reach the stop node
    while (circulator.hasNext(dir)) {
        // Check if the current node satisfies the predicate
        if (predicate.test(circulator.getCurrent())) {
            // Return the circulator
            return circulator;
        }

        // Move to the next node
        circulator.setCurrent(predicate.getNext(circulator.getCurrent(), dir));
    }

