final void addLineNumber(final int lineNumber) {
    // Determine the index of the line number in the lookup table
    int index = Arrays.binarySearch(lineNumbers, lineNumber);
    if (index < 0) {
        index = -(index + 1);
    }

    // Add the new line number to the lookup table
    if (index < length) {
        lineNumbers[index] = lineNumber;
    } else {
        int newLength = index + 1;
        int[] newLineNumbers = new int[newLength];
        System.arraycopy(lineNumbers, 0, newLineNumbers, 0, length);
        newLineNumbers[index] = lineNumber;
        lineNumbers = newLineNumbers;
    }
}

