List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
   List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
   for (E edge : graph.edges()) {
      Set<Integer> neighbors = new HashSet<>();
      neighbors.addAll(graph.neighborhoodOf(edge.from()));
      neighbors.addAll(graph.neighborhoodOf(edge.to()));
      for (Integer neighbor : neighbors) {
         Set<Integer> separator = new HashSet<>();
         separator.add(neighbor);
         separator.addAll(graph.DFS_Path(edge.from(), neighbor));
         separator.addAll(graph.DFS_Path(edge.to(), neighbor));
         List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
         for (Integer vertex : separator) {
            separatorList.add(new Pair<>(vertex, vertex));
         }
         globalSeparatorList.add(new Pair<>(separatorList, edge));
      }
   }
   return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (int i = 0; i < graph.size(); i++) {
        List<Pair<Integer,Integer>> minSeparators = computeMinimalSeparatorList(graph.get(i));
        for (Pair<Integer,Integer> minSeparator : minSeparators) {
            globalSeparatorList.add(Pair.of(minSeparator.getFirst(), minSeparator.getSecond()));
        }
    }
    return globalSeparatorList;
}

