private List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize an empty list to store the upper bounds
    List<Integer> upperBounds = new ArrayList<>();

    // Iterate over the keys and compute the upper bound for each key
    for (K key : keys) {
        // Initialize the upper bound for the current key
        int upperBound = Integer.MAX_VALUE;

        // Iterate over the rest of the keys and update the upper bound if necessary
        for (K otherKey : keys) {
            // Check if the current key is less than or equal to the other key
            if (key.compareTo(otherKey) <= 0) {
                // Update the upper bound if necessary
                upperBound = Math.min(upperBound, otherKey.compareTo(key));
            }
        }

        // Add the computed upper bound to the list
        upperBounds.add(upperBound);
    }

    // Return the list of upper bounds
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int minimum = Integer.MAX_VALUE;
        for (int j = i + 1; j < keys.size(); j++) {
            int diff = Math.abs(keys.get(i) - keys.get(j));
            minimum = Math.min(minimum, diff);
        }
        bounds.add(minimum);
    }
    return bounds;
}

