  // Compute the upper bound for each key.
  List<Integer> bounds = new ArrayList<Integer>();
  for (int i = 1; i < sortedKeys.size(); i++) {
    int current = i;
    int previous = current - 1;
    int diff = sortedKeys.get( current ).compareTo(sortedKeys.get(previous));
    if (diff < 0) {
