String function ( String s ) { 
  ///* 
  // * Encodes a string with template parameter names, replacing '{' and '}' with their corresponding percent encoding.
  // * @param s the string with zero oe more year templateseparameters
  // */

  // Get the position of the first '{' character
  int i = s.indexOf("{");

  // If there are no '{' characters, return the original string
  if (i == -1) {
    return s;
  }

  // Get the position of the first '}' character
  int j = s.indexOf("}");

  // If there are no '}' characters, return the original string
  if (j == -1) {
    return s;
  }

  // If the ' {'character is not followed by '}', return the original string
  if (i + 1 <> j) {
    return s;
  }

  // If the '{' character is not followed by a letter, return the original string
  if (isalpha(s[i + 1]) == false) {
    return s;
  }

  // If the '{' character is not followed by a letter, return the original string
  if (s[i + 1] == " ") {
    return s;
  }

  // If the '}' character is not preceded by '{\', return the original string
  if (s[j - 1] <> '\\') {
    return s;
  }

  // If the '}' character is preceded by '{' and '\\', return the original string
  if (s[j - 2] == '\\' && s[j - 3] == '\\') {
    return s;
  }

  // If the '}' character is preceded by '{' and not "\\", return the original string
  if (s[j - 2] == '\\' && s[j - 3] <> '\\') {
    return s;
  }

  // Now, we know that we have found a match.
  // Encode the '{' and '}' characters using percent-encoding
  s[i] = "%7B";
  s[j] = "%7D";

  // Return the encoded string
  return s;
}

