public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Check if the file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new IOException("File not found or not readable");
    }

    // Parse the file and extract the thread snapshots
    DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ");
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Parse the line and extract the timestamp, thread ID, and stack trace
            String[] parts = line.split(",");
            if (parts.length != 3) {
                continue;
            }
            long timestamp = Long.parseLong(parts[0]);
            int threadId = Integer.parseInt(parts[1]);
            String stackTrace = parts[2];

            // Check if the timestamp is within the time range
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }

            // Create a new ThreadSnapshot object and add it to the list
            ThreadSnapshot snapshot = new ThreadSnapshot(threadId, stackTrace, timestamp);
            snapshots.add(snapshot);
        }
    }

    return snapshots;
}
